// ===== CONFIG =====
// Companhias de energia atendidas pela Crefaz. Vazio = não filtra por companhia.
const ATENDIDAS = ['CPFL Paulista'];
// ==================

const norm = (s) => String(s ?? '').normalize('NFD').replace(/[\u0300-\u036f]/g, '').toLowerCase().trim();

function campos(j) {
  const out = {};
  // Formato bruto da Meta: field_data = [{ name, values: [...] }]
  const fd = j.field_data || j.data?.field_data;
  if (Array.isArray(fd)) fd.forEach((f) => (out[norm(f.name)] = Array.isArray(f.values) ? f.values.join(', ') : f.values));
  // Formato simplificado do n8n ou webhook de teste: { data: {...} } ou plano
  const plano = (j.data && typeof j.data === 'object' && !Array.isArray(j.data)) ? j.data : (j.body && typeof j.body === 'object' ? j.body : j);
  Object.entries(plano).forEach(([k, v]) => { if (typeof v !== 'object') out[norm(k)] = v; });
  return out;
}

const chave = (s) => norm(s).replace(/[_\s]+/g, ' ');
const pega = (c, ...nomes) => { for (const n of nomes) for (const k of Object.keys(c)) if (k.includes(n)) return c[k]; return null; };

return $input.all().map((it) => {
  const j = it.json;
  const c = campos(j);
  const nome = pega(c, 'full_name', 'nome_completo') ?? c['nome'] ?? c['name'] ?? null;
  const telefone = pega(c, 'phone', 'telefone', 'whatsapp', 'celular');
  const email = pega(c, 'email');
  const cidade = pega(c, 'city', 'cidade');
  const companhia = pega(c, 'companhia', 'energia', 'distribuidora');
  const contaNome = pega(c, 'titular', 'conta_no_nome', 'nome_na_conta', 'esta_no_seu_nome', 'no_seu_nome');
  const valor = pega(c, 'valor');
  const produto = pega(c, 'produto', 'tipo') || 'Empréstimo na conta de luz';

  let qualificado = true, motivo = null;
  if (contaNome != null && /^n(a|ã)o/.test(norm(contaNome))) { qualificado = false; motivo = 'Conta de luz não está no nome'; }
  if (qualificado && ATENDIDAS.length && companhia && !ATENDIDAS.map(chave).includes(chave(companhia))) { qualificado = false; motivo = 'Companhia de energia não atendida: ' + companhia; }

  return { json: {
    p_nome: nome,
    p_telefone: telefone,
    p_email: email,
    p_cidade: cidade,
    p_produto: produto,
    p_respostas: { ...c, companhia_energia: companhia, conta_no_nome: contaNome, valor },
    p_origem: j.leadgen_id || j.id ? 'meta' : 'manual',
    p_meta_lead_id: String(j.leadgen_id || j.id || '') || null,
    p_campanha: j.campaign_name || j.campaign?.name || null,
    p_anuncio: j.ad_name || j.ad?.name || null,
    p_qualificado: qualificado,
    p_motivo_fora_perfil: motivo,
    _resumo: { companhia, contaNome, valor }
  } };
});
